def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,data):
 p=Path(p);tmp=p.with_suffix('.tmp');tmp.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8');tmp.replace(p)
def safe(root,name):
 if '\\' in name or ':' in name or '..' in PurePosixPath(name).parts:raise ValueError('Unsafe path')
 p=(Path(root)/name).resolve()
 if not p.is_relative_to(Path(root).resolve()):raise ValueError('Unsafe path')
 return p
def unpack(raw,destination):
 destination=Path(destination).resolve()
 if destination.exists():raise ValueError('Use a new input/output directory')
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  entries=z.infolist()
  if len(entries)>300 or sum(i.file_size for i in entries)>100_000_000:raise ValueError('ZIP too large')
  names=set();paths=[]
  for item in entries:
   name=item.filename;key=str(safe(destination,name).relative_to(destination)).casefold()
   if key in names or stat.S_ISLNK(item.external_attr>>16) or item.flag_bits&1:raise ValueError('Duplicate/encrypted/symlink ZIP entry')
   names.add(key);paths.append((item,safe(destination,name)))
  if z.testzip() is not None:raise ValueError('ZIP CRC failed')
  destination.mkdir(parents=True)
  try:
   for item,p in paths:
    if item.is_dir():p.mkdir(parents=True,exist_ok=True)
    else:p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(z.read(item))
  except Exception:
   shutil.rmtree(destination);raise
 return destination

def ids_for(stage):
 if stage not in ('trial9','remaining26'):raise ValueError('Only trial9 or approved remaining26 stages exist; no all35 bypass')
 return CATALOG[stage]
def expected(lid):
 line=CATALOG['lines'][lid];a=CATALOG['assets'][line['assetId']]
 return {**a,'lineId':lid,'lineIds':[lid],'events':line['events']}
def identity(a):return {k:a[k] for k in ('assetId','lineId','lineIds','role','voiceId','text','filename','src','events')}
def check_asset(a):
 lid=a.get('lineId')
 if lid not in CATALOG['lines'] or identity(a)!=identity(expected(lid)):raise ValueError('Fixed ID/voice/text/event identity mismatch: '+str(lid))

def validate_output(output,complete=False):
 import numpy as np,soundfile as sf
 output=Path(output);m=read(output/'generated-manifest.json');stage=m.get('stage');jobs=ids_for(stage)
 if m.get('scope')!='park-'+('trial9' if stage=='trial9' else 'complete36')+'-review' or m['source']!=CATALOG['source'] or m['lines']!=CATALOG['lines'] or m['characters']!=CATALOG['characters'] or m['models']!=MODELS:raise ValueError('Wrong Park output manifest')
 allowed={CATALOG['lines'][i]['assetId'] for i in jobs}
 if stage=='remaining26':allowed|={CATALOG['lines'][i]['assetId'] for i in CATALOG['trial9']}|{CATALOG['sharedAssetId']}
 if not set(m['assets']).issubset(allowed) or (complete and set(m['assets'])!=allowed):raise ValueError('Missing or unexpected Park assets')
 protected_keys={CATALOG['lines'][i]['assetId'] for i in CATALOG['trial9']}|{CATALOG['sharedAssetId']}
 if (stage=='trial9' and m.get('protectedAssets')!={}) or (stage=='remaining26' and (set(m.get('protectedAssets',{}))!=protected_keys or m['protectedAssets'][CATALOG['sharedAssetId']]!=CATALOG['sharedSha256'])):raise ValueError('Protected asset locks changed')
 if not set(m['protectedAssets']).issubset(m['assets']):raise ValueError('Protected seed audio missing')
 for aid,a in m['assets'].items():
  check_asset(a)
  if aid!=a['assetId'] or sha(safe(output,a['src']))!=a['sha256']:raise ValueError('Audio SHA256 mismatch: '+aid)
  data,sr=sf.read(safe(output,a['src']))
  if data.ndim!=1 or not np.isfinite(data).all() or not .12<len(data)/sr<45 or abs(len(data)/sr-a['duration'])>.03:raise ValueError('Invalid WAV: '+aid)
  if aid in m.get('protectedAssets',{}) and a['sha256']!=m['protectedAssets'][aid]:raise ValueError('Accepted recording changed')
 return m

def validate_work(work):
 work=Path(work)
 if read(work/'manifest.json')!=CATALOG or read(work/'model-lock.json')!=MODELS:raise ValueError('Input catalog/model lock changed')
 for role in ('rosie','pirate'):
  ref=CATALOG['characters'][role]['reference']
  if ref['use']!='main' or sha(safe(work/'references',ref['file']))!=ref['sha256']:raise ValueError('Approved main reference changed: '+role)
 shared=CATALOG['assets'][CATALOG['sharedAssetId']]
 if sha(safe(work/'shared',shared['src']))!=CATALOG['sharedSha256']:raise ValueError('Approved shared Library WAV changed')

def approved_trial(path):
 m=validate_output(path,True)
 if m['stage']!='trial9':raise ValueError('A complete nine-line trial is required')
 review=validate_review(read(Path(path)/'voice-review.json'),m)
 if any(row['decision']!='accepted' for row in review['lines'].values()):raise ValueError('All nine must be manually accepted before remaining26')
 return m,review

def plan(work,stage='trial9',accepted_trial=None):
 validate_work(work);jobs=[expected(i) for i in ids_for(stage)]
 if stage=='remaining26':
  if accepted_trial is None:raise ValueError('Upload accepted nine-line results first')
  approved_trial(accepted_trial)
 return jobs

_QWEN_MODEL=None
_KOKORO_PIPELINE=None

def factory(role,work):
 import torch,numpy as np
 from huggingface_hub import snapshot_download,hf_hub_download
 voice=CATALOG['characters'][role]
 if role in ('rosie','pirate'):
  global _QWEN_MODEL
  from qwen_tts import Qwen3TTSModel
  spec=MODELS['Qwen/Qwen3-TTS-12Hz-1.7B-Base']
  if _QWEN_MODEL is None:
   _QWEN_MODEL=Qwen3TTSModel.from_pretrained(snapshot_download(spec['repo'],revision=spec['revision'],token=False),device_map='cuda:0',dtype=torch.bfloat16 if torch.cuda.is_bf16_supported() else torch.float16,attn_implementation='sdpa')
  ref=voice['reference'];prompt=_QWEN_MODEL.create_voice_clone_prompt(ref_audio=str(safe(Path(work)/'references',ref['file'])),ref_text=ref['ref_text'],x_vector_only_mode=False)
  def synth(text):
   wavs,sr=_QWEN_MODEL.generate_voice_clone(text=text,language='English',voice_clone_prompt=prompt,non_streaming_mode=True,max_new_tokens=2048)
   return np.asarray(wavs[0],dtype=np.float32),sr
  return synth,{'model':spec,'referenceSha256':ref['sha256'],'ref_text':ref['ref_text'],'voiceId':voice['voiceId'],'pitchProcessing':False}
 global _KOKORO_PIPELINE
 from kokoro import KModel,KPipeline
 spec=MODELS['hexgrad/Kokoro-82M'];dl=lambda f:hf_hub_download(spec['repo'],f,revision=spec['revision'],token=False)
 if _KOKORO_PIPELINE is None:
  model=KModel(repo_id=spec['repo'],config=dl('config.json'),model=dl('kokoro-v1_0.pth')).to('cpu').eval()
  _KOKORO_PIPELINE=KPipeline(lang_code='a',repo_id=spec['repo'],model=model,device='cpu')
 vpath=dl('voices/'+voice['voiceId']+'.pt');tensor=torch.load(vpath,weights_only=True,map_location='cpu')
 def synth(text):
  with torch.inference_mode():chunks=list(_KOKORO_PIPELINE(text,voice=tensor,speed=1.,split_pattern=None))
  if not chunks:raise ValueError('Kokoro produced no audio')
  return np.concatenate([c.audio.cpu().numpy() for c in chunks]),24000
 return synth,{'model':spec,'voiceId':voice['voiceId'],'voiceTensorSha256':sha(vpath),'speed':1.,'pitchProcessing':False}

def release_models():
 global _QWEN_MODEL,_KOKORO_PIPELINE
 _QWEN_MODEL=None;_KOKORO_PIPELINE=None;gc.collect()
 if 'torch' in sys.modules and sys.modules['torch'].cuda.is_available():sys.modules['torch'].cuda.empty_cache()

def generate(work,output,stage='trial9',run=False,confirmation='',accepted_trial=None,factory_override=None):
 jobs=plan(work,stage,accepted_trial)
 if not run:return {'dryRun':True,'generated':0,'stage':stage,'count':len(jobs),'jobs':jobs}
 if confirmation!=('CONFIRM_PARK_NINE' if stage=='trial9' else 'CONFIRM_PARK_REMAINING_26'):raise ValueError('Review dry-run and explicitly enable only this stage')
 # No model/GPU allocation until both the stage acceptance and explicit run gate passed.
 import torch,numpy as np,soundfile as sf
 if factory_override is None and not torch.cuda.is_available():raise RuntimeError('Use free Colab T4; no paid fallback')
 work=Path(work).resolve();output=Path(output).resolve()
 if output.is_relative_to(work) or work.is_relative_to(output):raise ValueError('Output must be independent of input')
 if accepted_trial:
  trial=Path(accepted_trial).resolve()
  if output.is_relative_to(trial) or trial.is_relative_to(output):raise ValueError('Do not overwrite accepted trial folder')
 mf=output/'generated-manifest.json'
 if output.exists() and any(output.iterdir()) and not mf.exists():raise ValueError('Choose new output folder')
 if mf.exists():m=validate_output(output)
 else:
  m={'schemaVersion':1,'scope':'park-'+('trial9' if stage=='trial9' else 'complete36')+'-review','stage':stage,'source':CATALOG['source'],'characters':CATALOG['characters'],'models':MODELS,'lines':CATALOG['lines'],'assets':{},'protectedAssets':{},'productionApproved':False}
  output.mkdir(parents=True,exist_ok=True);(output/'audio').mkdir(exist_ok=True)
  if stage=='remaining26':
   seed,review=approved_trial(accepted_trial);m['seedReviews']=review['lines']
   for aid,a in seed['assets'].items():
    (output/a['src']).write_bytes(safe(accepted_trial,a['src']).read_bytes());m['assets'][aid]=a;m['protectedAssets'][aid]=a['sha256']
   lid=next(i for i,l in CATALOG['lines'].items() if l['assetId']==CATALOG['sharedAssetId']);a=expected(lid);p=safe(work/'shared',a['src'])
   data,sr=sf.read(p);a={**a,'sha256':CATALOG['sharedSha256'],'sampleRate':sr,'duration':len(data)/sr,'status':'reused-approved','review':'accepted-library-shared','visemes':[]}
   (output/a['src']).write_bytes(p.read_bytes());m['assets'][a['assetId']]=a;m['protectedAssets'][a['assetId']]=a['sha256']
  save(mf,m)
 if m['stage']!=stage:raise ValueError('Cannot mix stages in existing output')
 if stage=='remaining26':
  seed,_=approved_trial(accepted_trial);protected={aid:a['sha256'] for aid,a in seed['assets'].items()};protected[CATALOG['sharedAssetId']]=CATALOG['sharedSha256']
  if m['protectedAssets']!=protected:raise ValueError('Accepted seed source mismatch')
 completed=0
 try:
  for role in ('rosie','pirate','mermaid','vampire_ring'):
   pending=[a for a in jobs if a['role']==role and a['assetId'] not in m['assets']]
   if not pending:continue
   if role=='mermaid':release_models()
   synth,provenance=(factory_override or factory)(role,work)
   for a in pending:
    dest=safe(output,a['src'])
    if dest.exists():raise ValueError('Unverified WAV already exists; use new folder')
    seed=int(hashlib.sha256(('park:'+a['assetId']).encode()).hexdigest()[:8],16);random.seed(seed);np.random.seed(seed);torch.manual_seed(seed)
    if torch.cuda.is_available():torch.cuda.manual_seed_all(seed)
    data,sr=synth(a['text']);data=np.asarray(data,dtype=np.float32)
    if data.ndim!=1 or not np.isfinite(data).all() or not .12<len(data)/sr<45 or np.sqrt(np.mean(data**2))<.001:raise ValueError('Invalid generated audio')
    gain=min(1.,.98/max(float(np.max(np.abs(data))),1e-9));sf.write(dest,data*gain,sr,subtype='PCM_16')
    m['assets'][a['assetId']]={**a,'sha256':sha(dest),'duration':len(data)/sr,'sampleRate':sr,'status':'generated','seed':seed,'gain':gain,'generation':provenance,'visemes':[],'review':'pending-human-listening'}
    save(mf,m);completed+=1;print(role,a['lineId'],a['text'])
   del synth;gc.collect()
 finally:release_models()
 validate_output(output,True)
 return {'generated':completed,'output':str(output),'stage':stage,'assetCount':len(m['assets'])}

def review_identity(a):return {k:a[k] for k in ('assetId','lineId','role','voiceId','text','sha256')}
def new_review(m):
 rows={}
 for aid,a in m['assets'].items():
  prior=m.get('seedReviews',{}).get(aid,{})
  rows[aid]={**review_identity(a),'decision':'accepted' if aid in m['protectedAssets'] else 'pending','notes':prior.get('notes',''),'locked':aid in m['protectedAssets']}
 return {'schemaVersion':1,'scope':'park-human-review','stage':m['stage'],'source':m['source'],'productionApproved':False,'lines':rows}
def validate_review(review,m,allow_partial=False):
 if review.get('scope')!='park-human-review' or review.get('stage')!=m['stage'] or review.get('source')!=m['source']:raise ValueError('Review does not belong to this Park stage')
 keys=set(review.get('lines',{}));assets=set(m['assets'])
 if (not allow_partial and keys!=assets) or not keys.issubset(assets):raise ValueError('Review asset set mismatch')
 for aid,row in review['lines'].items():
  if any(row.get(k)!=v for k,v in review_identity(m['assets'][aid]).items()):raise ValueError('Review/audio identity changed')
  if row.get('decision') not in ('accepted','needs-retake','pending') or not isinstance(row.get('notes'),str) or row.get('locked')!=(aid in m['protectedAssets']):raise ValueError('Invalid review decision/lock')
  if aid in m['protectedAssets'] and row['decision']!='accepted':raise ValueError('Accepted/shared audio is locked')
 result=new_review(m)
 result['lines'].update(review['lines']);return result

def persist_review(output,review,m):
 review=validate_review(review,m);review['updatedAt']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 save(Path(output)/'voice-review.json',review)
 save(Path(output)/'retake-request.json',{'scope':'park-specified-retake-request','generationEnabled':False,'stage':m['stage'],'jobs':[row for aid,row in review['lines'].items() if aid not in m['protectedAssets'] and row['decision']=='needs-retake']})
 return review

def export_results(output,review=None):
 output=Path(output);m=validate_output(output);rp=output/'voice-review.json'
 review=validate_review(review if review is not None else read(rp) if rp.exists() else new_review(m),m,True)
 review=persist_review(output,review,m);dest=output.parent/('park-'+m['stage']+'-reviewed-'+uuid.uuid4().hex[:8]+'.zip')
 with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED) as z:
  for name in ('generated-manifest.json','voice-review.json','retake-request.json'):z.write(output/name,name)
  for a in m['assets'].values():z.write(safe(output,a['src']),a['src'])
  cards=[]
  for aid,a in m['assets'].items():
   row=review['lines'][aid];cards.append('<section><h2>'+html.escape(a['role']+' / '+a['voiceId'])+'</h2><p>'+html.escape(a['lineId'])+'</p><p>'+html.escape(a['text'])+'</p><audio controls preload="none" src="'+html.escape(a['src'],quote=True)+'"></audio><p>'+html.escape(row['decision']+' / '+row['notes'])+'</p></section>')
  z.writestr('review.html','<!doctype html><meta charset="utf-8"><title>Park人工驗收</title><style>body{max-width:850px;margin:auto;font:17px/1.6 sans-serif}section{padding:16px;border:1px solid #aaa;margin:12px}</style><h1>Park配音人工驗收</h1><p>未驗收不等於接受；不修改正式遊戲。保留audio資料夾。</p>'+''.join(cards))
 return dest

def restore_results(raw,parent):
 dest=unpack(raw,Path(parent)/('park-restored-'+uuid.uuid4().hex[:10]));manifests=list(dest.rglob('generated-manifest.json'))
 if len(manifests)!=1:raise ValueError('Need exactly one output manifest')
 out=manifests[0].parent;m=validate_output(out)
 if set(dest.rglob('*.wav'))!={safe(out,a['src']) for a in m['assets'].values()}:raise ValueError('ZIP WAV count mismatch')
 rp=out/'voice-review.json'
 if rp.exists():validate_review(read(rp),m,True)
 return out

_UI_TOKEN=None

def show_review(output):
 from IPython.display import Audio,display,clear_output
 import ipywidgets as widgets
 from google.colab import files
 output=Path(output);m=validate_output(output);rp=output/'voice-review.json';review=validate_review(read(rp),m,True) if rp.exists() else new_review(m)
 persist_review(output,review,m)
 global _UI_TOKEN
 token=uuid.uuid4().hex;_UI_TOKEN=token;controls={};restoring=False;status=widgets.HTML();messages=widgets.Output()
 def summary(text=''):
  rows=list(review['lines'].values());target=9 if m['stage']=='trial9' else 36
  status.value=html.escape(text)+'<p>完成音檔 '+str(len(rows))+' / '+str(target)+'；已接受 '+str(sum(r['decision']=='accepted' for r in rows))+'；需重錄 '+str(sum(r['decision']=='needs-retake' for r in rows))+'；未決定 '+str(sum(r['decision']=='pending' for r in rows))+'。自動保存於OUTPUT/voice-review.json。</p>'
 def changed(aid,c,n):
  def callback(_):
   if token!=_UI_TOKEN or restoring:return
   review['lines'][aid].update(decision=c.value,notes=n.value)
   try:persist_review(output,review,m);summary('已保存')
   except Exception as e:summary('保存失敗：'+str(e))
  return callback
 zipbutton=widgets.Button(description='下載WAV與驗收紀錄ZIP',layout=widgets.Layout(width='230px'))
 jsonbutton=widgets.Button(description='匯出驗收JSON',layout=widgets.Layout(width='180px'))
 loadbutton=widgets.Button(description='重新載入驗收JSON',layout=widgets.Layout(width='200px'))
 def zip_click(_):
  with messages:
   clear_output(wait=True)
   try:files.download(str(export_results(output,review)));summary('已核對並匯出目前所有音檔；請確認完成數')
   except Exception as e:print(e)
 def json_click(_):persist_review(output,review,m);files.download(str(rp))
 def load_click(_):
  nonlocal review,restoring
  with messages:
   clear_output(wait=True)
   try:
    uploaded=files.upload()
    if len(uploaded)!=1:raise ValueError('只選一個voice-review.json')
    incoming=validate_review(json.loads(next(iter(uploaded.values())).decode('utf-8-sig')),m,True)
    if rp.exists():rp.with_name('voice-review-backup-'+uuid.uuid4().hex[:8]+'.json').write_bytes(rp.read_bytes())
    review=incoming;restoring=True
    for aid,(c,n) in controls.items():c.value=review['lines'][aid]['decision'];n.value=review['lines'][aid]['notes']
    restoring=False;persist_review(output,review,m);summary('已載入；載入前紀錄另存備份')
   except Exception as e:restoring=False;print('載入失敗：',e)
 zipbutton.on_click(zip_click);jsonbutton.on_click(json_click);loadbutton.on_click(load_click)
 display(widgets.HTML('<h2>Park逐句人工驗收</h2><p>本介面只讀音檔，不執行推論。Colab重置會清暫存，離開前請下載ZIP；新執行階段可用CPU恢復筆記本重新上傳ZIP。</p>'),widgets.HBox([zipbutton,jsonbutton,loadbutton]),status,messages)
 for aid,a in m['assets'].items():
  display(widgets.HTML('<hr><h3>'+html.escape(a['role']+' / '+a['voiceId'])+'</h3><p>'+html.escape(a['text'])+'</p><small>'+html.escape(a['lineId']+' · '+aid)+'</small>'))
  display(Audio(filename=str(safe(output,a['src'])),autoplay=False))
  row=review['lines'][aid]
  if aid in m['protectedAssets']:
   display(widgets.HTML('<p><b>已接受（鎖定：已核准九句或Library共用原音）</b></p>'));continue
  c=widgets.Dropdown(options=[('尚未決定','pending'),('接受此句','accepted'),('需要重錄','needs-retake')],value=row['decision'],description='驗收：')
  n=widgets.Textarea(value=row['notes'],description='備註：',placeholder='音色太成熟、老船長感不足、語速、漏詞、發音等',continuous_update=True,layout=widgets.Layout(width='95%',height='75px'))
  callback=changed(aid,c,n);c.observe(callback,names='value');n.observe(callback,names='value');controls[aid]=(c,n);display(c,n)
 summary('介面就緒；已還原先前保存的選擇')
 return {'controls':controls,'review':review,'output':output}
